<?php include "db.php";if(!isset($_SESSION['user_id'])){header("Location: login.php");exit();}$bus_id=(int)($_GET['bus_id']??0);$stmt=mysqli_prepare($conn,"SELECT * FROM buses WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$bus_id);mysqli_stmt_execute($stmt);$bus=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$bus)die("Bus not found. <a href='buses.php'>Back</a>");$msg="";if(isset($_POST['book'])){$passenger=trim($_POST['passenger_name']);$age=(int)$_POST['age'];$seat=trim($_POST['seat_no']);if($passenger===""||$age<1||$age>110||$seat===""){$msg="Enter valid passenger details and seat number.";}elseif($bus['travel_date']<date('Y-m-d')||($bus['travel_date']==date('Y-m-d')&&$bus['departure_time']<=date('H:i:s'))){$msg="This bus has already departed.";}else{$stmt=mysqli_prepare($conn,"SELECT id FROM bookings WHERE bus_id=? AND seat_no=? AND status='Booked'");mysqli_stmt_bind_param($stmt,"is",$bus_id,$seat);mysqli_stmt_execute($stmt);$exists=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if($exists){$msg="That seat is already booked. Please choose another seat.";}else{$stmt=mysqli_prepare($conn,"INSERT INTO bookings(user_id,bus_id,passenger_name,age,seat_no,total_price,status) VALUES(?,?,?,?,?,?,'Booked')");mysqli_stmt_bind_param($stmt,"iisisd",$_SESSION['user_id'],$bus_id,$passenger,$age,$seat,$bus['price']);if(mysqli_stmt_execute($stmt)){header("Location: my_bookings.php?success=1");exit();}else{$msg="Booking failed: ".mysqli_error($conn);}}}}$taken=[];$stmt=mysqli_prepare($conn,"SELECT seat_no FROM bookings WHERE bus_id=? AND status='Booked'");mysqli_stmt_bind_param($stmt,"i",$bus_id);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);while($x=mysqli_fetch_assoc($res))$taken[]=$x['seat_no'];?>
<!DOCTYPE html><html><head><title>Book Bus Ticket</title><link rel="stylesheet" href="style.css"></head><body><header><h1>GoBus</h1><nav><a href="index.php">Home</a><a href="buses.php">Find Buses</a><a href="my_bookings.php">My Tickets</a></nav></header><div class="container"><div class="form-box"><h2>Book: <?php echo htmlspecialchars($bus['bus_name']); ?></h2><p><?php echo htmlspecialchars($bus['source'].' to '.$bus['destination']); ?> · <?php echo $bus['travel_date'].' '.$bus['departure_time']; ?></p><p>Fare: ₹<?php echo number_format($bus['price'],2); ?></p><?php if($msg)echo '<p class="error">'.htmlspecialchars($msg).'</p>'; ?><form method="post"><label>Passenger name</label><input name="passenger_name" required><label>Age</label><input type="number" name="age" min="1" max="110" required><label>Seat number</label><select name="seat_no" required><option value="">Choose seat</option><?php for($i=1;$i<=$bus['total_seats'];$i++){ $s='S'.$i;if(!in_array($s,$taken)){echo '<option value="'.$s.'">'.$s.'</option>';}}?></select><button name="book">Confirm Ticket</button></form><p><small>Demo project: payment gateway and confirmation email are not enabled.</small></p></div></div></body></html>